const headers = $('Webhook: add-calendar-contact').first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');

return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const body = $('Webhook: add-calendar-contact').first().json.body || {};

// Wrong-typed values (objects/arrays) become '' instead of "[object Object]"; control characters are stripped.
const clean = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v) : '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
const EMAIL_RE = /^[^\s@<>"'`,;()\[\]\\]+@[^\s@<>"'`,;()\[\]\\]+\.[^\s@<>"'`,;()\[\]\\]{2,}$/;
const toInt = (v) => { const n = parseInt(v, 10); return Number.isInteger(n) && n > 0 ? n : null; };

let first = clean(body.first_name);
let last = clean(body.last_name);
// A single "name" field is split on the first space, so the form can send what the rep typed.
if (!first && clean(body.name)) { const parts = clean(body.name).split(' '); first = parts[0]; last = parts.slice(1).join(' '); }
if (!first) throw new Error('A contact name is required.');
if (first.length > 150 || last.length > 150) throw new Error('The name is too long (maximum 150 characters).');

const email = clean(body.email).toLowerCase();
if (email && (email.length > 255 || !EMAIL_RE.test(email))) throw new Error('That email address does not look valid.');
const phone = clean(body.phone);
const digits = phone.replace(/\D/g, '');
if (phone && (phone.length > 50 || digits.length < 7 || digits.length > 15)) throw new Error('That phone number does not look valid.');

return [{ json: {
  first_name: first, last_name: last, email, phone, phone_digits: digits,
  owner_id: toInt(body.owner_id) || requester.id,
  account_id: toInt(body.account_id),
  requester_id: requester.id,
} }];
